{
  "format": 1,
  "name": "research-brief",
  "version": "1.1.0",
  "description": "Search a host-owned corpus and return an exact-locator cited brief.",
  "files": {
    "analyst.md": "db8bf5193caafece768ccdddd364e71a48fadecf7d5c91c136b0c1c0ea49e6ae"
  },
  "dependencies": [
    {
      "digest": "6f21c4b2360e3d48b2c63bc9e36c2a307a276a51ec3cedd244d5ec58c79daf61",
      "name": "evidence-base",
      "version": "1.0.0"
    }
  ],
  "tools": {
    "knowledge_search": {
      "effect": "read_only",
      "permissions": [
        "knowledge:read"
      ]
    }
  },
  "credentials": [],
  "roles": [
    {
      "name": "analyst",
      "instructions": "analyst.md",
      "includes": [
        {
          "dependency": "evidence-base",
          "path": "guidance.md"
        }
      ],
      "tools": [
        "knowledge_search"
      ],
      "output": {
        "type": "validated",
        "policy": {
          "type": "located_cited_report",
          "max_repairs": 2
        }
      }
    }
  ],
  "templates": [
    {
      "id": "source-summary",
      "title": "Local source summary with exact locators",
      "description": "Exact locators and ordinal markers; original model output retained.",
      "input_schema": {
        "type": "object",
        "properties": {
          "goal": {
            "type": "string",
            "minLength": 1,
            "maxLength": 4096
          }
        },
        "required": [
          "goal"
        ],
        "additionalProperties": false
      },
      "workflow": {
        "type": "dag",
        "definition": {
          "nodes": [
            {
              "id": "result",
              "task": "analyst",
              "depends_on": [],
              "params": null,
              "condition": {
                "type": "always"
              },
              "allow_skipped_dependencies": false,
              "select": {}
            }
          ]
        }
      }
    }
  ],
  "connectors": []
}

